package com.forgeci.api;
import com.forgeci.application.github.GitHubConnectionService; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/connections/github") public class GitHubConnectionController {private final GitHubConnectionService service; public GitHubConnectionController(GitHubConnectionService s){service=s;} @GetMapping("/authorize") ResponseEntity<Void> authorize(Authentication a){return ResponseEntity.status(HttpStatus.FOUND).location(URI.create(service.authorizeUrl(UUID.fromString(a.getName())))).build();} @GetMapping("/callback") ResponseEntity<Void> callback(@RequestParam String state,@RequestParam String code)throws Exception{String[] p=state.split(":");if(p.length<1)throw new IllegalArgumentException("Invalid state");service.callback(UUID.fromString(p[0]),state,code);return ResponseEntity.status(HttpStatus.FOUND).location(URI.create("/settings?github=connected")).build();} @DeleteMapping ResponseEntity<Void> disconnect(Authentication a){service.disconnect(UUID.fromString(a.getName()));return ResponseEntity.noContent().build();} }
